using System.Globalization;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using System.Text.RegularExpressions;
using DocxHeaderExtractor.Core.Models;

namespace IdentityPromotionBenchmarkV4FB;

internal static class Program
{
    private const string SourceRelative = "artifacts/identity-benchmark/v2/source-catalog.json";
    private const string V4Root = "artifacts/identity-benchmark/v4/pruning-challenger";
    private const string OutputRelative = "artifacts/identity-benchmark/v4/context-projection";
    private const int ExpectedCount = 7702;
    private const int PreviousOccurrenceCount = 2;
    private const int NextOccurrenceCount = 2;
    private const int MaxInterveningOccurrences = 8;
    private const int MaxStructuralPeers = 4;
    private const int MaxPacketOccurrences = 26;
    private const string ProjectionVersion = "v4f-b-bounded-source-evidence-projection-v1";
    private static readonly JsonSerializerOptions ReadOptions = new(JsonSerializerDefaults.Web) { PropertyNameCaseInsensitive = true };
    private static readonly JsonSerializerOptions WriteOptions = new(JsonSerializerDefaults.Web) { WriteIndented = true };
    private static readonly Regex ContinuationMarker = new(@"\(\s*(?:cont(?:['’]d)?|continued)\s*\)|\bcontinued\b|tiếp\s+(?:theo|tục)", RegexOptions.IgnoreCase | RegexOptions.CultureInvariant | RegexOptions.Compiled);
    private static readonly Regex BranchMarker = new(@"\[(?:option|alternative|phương\s+án)\s*[^\]]*\]", RegexOptions.IgnoreCase | RegexOptions.CultureInvariant | RegexOptions.Compiled);

    public static int Main(string[] args)
    {
        try { Run(Path.GetFullPath(args.Length == 1 ? args[0] : Directory.GetCurrentDirectory())); return 0; }
        catch (Exception ex) { Console.Error.WriteLine($"V4F_B_ERROR={ex}"); return 2; }
    }

    private static void Run(string root)
    {
        var sourcePath = Full(root, SourceRelative);
        var v4ManifestPath = Full(root, V4Root + "/manifest.json");
        var shortlistPath = Full(root, V4Root + "/shortlist.json");
        var requestPath = Full(root, V4Root + "/request-manifest.json");
        var source = Read(sourcePath); var manifest = Read(v4ManifestPath); var shortlist = Read(shortlistPath); var frozenRequests = Read(requestPath);
        var input = VerifyInputs(source, manifest, shortlist, frozenRequests, sourcePath, v4ManifestPath, shortlistPath, requestPath);
        if (!input.Pass) throw new InvalidDataException("BLOCKED_ON_V4F_INPUT_DRIFT: " + string.Join(", ", input.Failures));
        var sourceFingerprint = source.RootElement.GetProperty("catalogFingerprint").GetString()!;
        var sourceDocs = source.RootElement.GetProperty("sourceDocuments").EnumerateArray().ToDictionary(x => x.GetProperty("documentId").GetString()!, x => new SourceDoc(x.GetProperty("documentId").GetString()!, x.GetProperty("sourceSha256").GetString()!, x.GetProperty("sourcePath").GetString()!), StringComparer.Ordinal);
        var allNodes = source.RootElement.GetProperty("sourceOccurrences").EnumerateArray().Select(x => new Occurrence(x.GetProperty("nodeId").GetString()!, x.GetProperty("text").GetString()!, x.GetProperty("documentOrder").GetInt32())).ToArray();
        var byDoc = allNodes.GroupBy(x => DocumentOf(x.NodeId), StringComparer.Ordinal).ToDictionary(g => g.Key, g => g.OrderBy(x => x.DocumentOrder).ThenBy(x => x.NodeId, StringComparer.Ordinal).ToArray(), StringComparer.Ordinal);
        var candidates = shortlist.RootElement.GetProperty("candidates").EnumerateArray().Select(ReadCandidate).OrderBy(x => x.PairId, StringComparer.Ordinal).ToArray();
        var frozen = frozenRequests.RootElement.GetProperty("requests").EnumerateArray().Select(x => new { id = x.GetProperty("requestId").GetString()!, bytes = x.GetProperty("requestBytes").GetInt64() }).ToDictionary(x => x.id, x => x.bytes, StringComparer.Ordinal);
        var config = new { projectionVersion = ProjectionVersion, previousOccurrenceCount = PreviousOccurrenceCount, nextOccurrenceCount = NextOccurrenceCount, maxInterveningOccurrences = MaxInterveningOccurrences, maxAncestorDepth = 0, maxStructuralPeers = MaxStructuralPeers, maxPacketOccurrences = MaxPacketOccurrences, ordering = "documentOrder ASC, sourceOccurrenceId ASC", sourceOnly = true, goldDerivedInput = false, semanticRelations = "not projected" };
        var configJson = JsonSerializer.Serialize(config, WriteOptions) + Environment.NewLine; var configHash = Sha256Text(configJson);
        var analyses = new List<Analysis>(candidates.Length); var duplicateIds = new HashSet<string>(StringComparer.Ordinal); var limitViolations = new List<string>();
        foreach (var candidate in candidates)
        {
            if (!byDoc.TryGetValue(candidate.DocumentId, out var docNodes)) throw new InvalidDataException("V4F_B_UNKNOWN_DOCUMENT:" + candidate.DocumentId);
            var index = docNodes.ToDictionary(x => x.NodeId, StringComparer.Ordinal); if (!index.TryGetValue(candidate.Left, out var left) || !index.TryGetValue(candidate.Right, out var right)) throw new InvalidDataException("V4F_B_UNKNOWN_OCCURRENCE:" + candidate.PairId);
            var packet = BuildPacket(candidate, left, right, docNodes, sourceDocs[candidate.DocumentId], sourceFingerprint, configHash);
            var bytes = JsonSerializer.SerializeToUtf8Bytes(packet, WriteOptions); var hash = Convert.ToHexString(SHA256.HashData(bytes)).ToLowerInvariant();
            var rebuilt = BuildPacket(candidate, left, right, docNodes, sourceDocs[candidate.DocumentId], sourceFingerprint, configHash);
            var rebuiltBytes = JsonSerializer.SerializeToUtf8Bytes(rebuilt, WriteOptions); var rebuiltHash = Convert.ToHexString(SHA256.HashData(rebuiltBytes)).ToLowerInvariant();
            if (!bytes.SequenceEqual(rebuiltBytes) || hash != rebuiltHash) throw new InvalidDataException("V4F_B_PACKET_RECONSTRUCTION_MISMATCH:" + candidate.PairId);
            if (!duplicateIds.Add(hash)) { /* identical packets are legal only when their candidate IDs differ; packet identity remains in bytes */ }
            var count = PacketOccurrenceIds(packet).Distinct(StringComparer.Ordinal).Count(); if (count > MaxPacketOccurrences) limitViolations.Add(candidate.PairId + ":occurrences=" + count);
            analyses.Add(new(candidate.PairId, candidate.DocumentId, bytes.Length, frozen[candidate.PairId], hash, packet, count));
        }
        if (limitViolations.Count != 0) throw new InvalidDataException("V4F_B_PROJECTION_LIMIT_EXCEEDED:" + limitViolations[0]);
        var output = Full(root, OutputRelative); Directory.CreateDirectory(output);
        var packetManifest = analyses.Select(x => new { packetId = "packet:" + x.CandidateId, candidateId = x.CandidateId, documentId = x.DocumentId, packetBytes = x.Bytes, packetSha256 = x.Sha256, oldRequestBytes = x.OldBytes, sourceOccurrenceIds = PacketOccurrenceIds(x.Packet).Distinct(StringComparer.Ordinal).Order(StringComparer.Ordinal).ToArray(), packetClass = PacketClass(x.Packet), reconstruction = new { sourceCatalogRelativePath = SourceRelative, sourceCatalogFingerprint = sourceFingerprint, candidateId = x.CandidateId, projectionConfigSha256 = configHash, packetBodiesPersisted = false } }).ToArray();
        Write(output + "/projection-config.json", config);
        Write(output + "/projection-contract.json", new { artifactKind = "a99_identity_benchmark_v4f_b_projection_contract", schemaVersion = "a99-v4f-b-projection-contract-v1", projectionVersion = ProjectionVersion, components = new[] { "PairOccurrenceEvidence", "LocalOrderEvidence", "StructuralEvidence", "NumberingEvidence", "ScopeEvidence", "LayoutEvidence", "VisualSourceEvidence" }, pairCore = "source-backed IDs, surfaces, order, source kind/container", localContext = "bounded previous/next occurrences and capped intervening occurrences", structuralContext = "source-container and bounded same-container peers only; hierarchy/ancestor fields unavailable in frozen catalog", relationalSourceFacts = "order distance, normalized equality, literal marker facts, candidate generation reasons", semanticConclusions = false, numericOffsets = false, goldAccess = false, sourceAuthority = "frozen V2 source catalog" });
        Write(output + "/evidence-availability.json", BuildAvailability(analyses));
        Write(output + "/packet-size-distribution.json", BuildSize(analyses));
        Write(output + "/payload-decomposition.json", BuildPayload(analyses));
        Write(output + "/packet-manifest.json", new { artifactKind = "a99_identity_benchmark_v4f_b_packet_manifest", schemaVersion = "a99-v4f-b-packet-manifest-v1", packetCount = analyses.Count, packetBodiesPersisted = false, canonicalOrdering = "candidateId ASC", projectionConfigSha256 = configHash, packets = packetManifest });
        Write(output + "/firewall.json", new { artifactKind = "a99_identity_benchmark_v4f_b_firewall", schemaVersion = "a99-v4f-b-firewall-v1", goldReadCount = 0, v4ebEvaluationReadCount = 0, providerCalls = 0, modelCalls = 0, candidateCountChanged = false, candidateOrderAffectsPacket = false, requestPromptChanged = false, relationFieldsConsumed = false, semanticConclusionFieldsProjected = false, noProviderTransport = true, packetBodiesPersisted = false, reconstructionFailures = 0, projectionLimitViolations = limitViolations.Count, goldMutationReplay = "not performed; implementation is source-only and has no Gold dependency" });
        Write(output + "/manifest.json", new { artifactKind = "a99_identity_benchmark_v4f_b_manifest", schemaVersion = "a99-v4f-b-manifest-v1", status = "READY_FOR_V4F_PROJECTED_REQUEST_FREEZE", parent = "V4F-A@8e7165d", candidateCount = candidates.Length, projectedPacketCount = analyses.Count, shortlistSha256 = Sha256File(shortlistPath), requestManifestSha256 = Sha256File(requestPath), sourceCatalogSha256 = Sha256File(sourcePath), sourceCatalogFingerprint = sourceFingerprint, sourcePacketHashes = sourceDocs.Values.OrderBy(x => x.DocumentId, StringComparer.Ordinal), projectionConfigSha256 = configHash, projectionVersion = ProjectionVersion, oldRequestContext = new { totalBytes = analyses.Sum(x => (long)x.OldBytes), estimatedTokens = analyses.Sum(x => (long)Estimate(checked((int)x.OldBytes))) }, newProjectedContext = new { totalBytes = analyses.Sum(x => (long)x.Bytes), estimatedTokens = analyses.Sum(x => (long)Estimate(x.Bytes)) }, exactReconstruction = "PASS", goldReadCount = 0, v4ebEvaluationReadCount = 0, providerCalls = 0, modelCalls = 0, candidateSetChanged = false, goldUsedForSelection = false, nextGate = "READY_FOR_V4F_PROJECTED_REQUEST_FREEZE", classes = analyses.GroupBy(x => PacketClass(x.Packet), StringComparer.Ordinal).OrderBy(x => x.Key, StringComparer.Ordinal).Select(x => new { packetClass = x.Key, count = x.Count() }).ToArray() });
        File.WriteAllText(output + "/report.md", BuildReport(analyses, sourceDocs, configHash), new UTF8Encoding(false));
        Console.WriteLine($"V4F_B_COMPLETE candidates={candidates.Length} newBytes={analyses.Sum(x => (long)x.Bytes)} oldBytes={analyses.Sum(x => (long)x.OldBytes)} configSha={configHash}");
    }

    private static Packet BuildPacket(Candidate c, Occurrence left, Occurrence right, Occurrence[] nodes, SourceDoc source, string fingerprint, string configHash)
    {
        var li = Array.IndexOf(nodes, left); var ri = Array.IndexOf(nodes, right); var ordered = li <= ri ? (li, ri) : (ri, li); var interveningAll = nodes.Skip(ordered.Item1 + 1).Take(Math.Max(0, ordered.Item2 - ordered.Item1 - 1)).ToArray(); var intervening = Bounded(interveningAll, MaxInterveningOccurrences).Select(x => Core(x, source)).ToArray();
        var local = new LocalContext(Neighbors(nodes, li, -1, PreviousOccurrenceCount, source), Neighbors(nodes, li, 1, NextOccurrenceCount, source), Neighbors(nodes, ri, -1, PreviousOccurrenceCount, source), Neighbors(nodes, ri, 1, NextOccurrenceCount, source), intervening, interveningAll.Length > intervening.Length, interveningAll.Length);
        var structural = new StructuralContext(new[] { SourceContainer(left.NodeId), SourceContainer(right.NodeId) }.Distinct(StringComparer.Ordinal).Order(StringComparer.Ordinal).ToArray(), StructuralPeers(nodes, li, ri));
        var leftCore = Core(left, source); var rightCore = Core(right, source);
        var relational = new RelationalFacts(Math.Abs(left.DocumentOrder - right.DocumentOrder), Normalize(left.Text) == Normalize(right.Text), Markers(left.Text), Markers(right.Text), Branches(left.Text), Branches(right.Text), c.Reasons.Order(StringComparer.Ordinal).ToArray());
        var availability = new EvidenceAvailability("AVAILABLE", "AVAILABLE", "AVAILABLE", "UNAVAILABLE", "UNAVAILABLE", "UNAVAILABLE", "UNAVAILABLE", interveningAll.Length > 0 ? "AVAILABLE" : "UNAVAILABLE");
        var missing = new[] { "numbering", "scope", "layout", "visual" };
        return new("a99_identity_benchmark_v4f_b_pair_evidence_packet", "v4f-b-pair-evidence-packet-v1", c.PairId, c.DocumentId, new[] { leftCore, rightCore }, local, structural, relational, availability, new[] { new EvidenceAuthority("FROZEN_SOURCE_CATALOG", "source occurrence text/order/container", "AVAILABLE"), new EvidenceAuthority("FROZEN_SOURCE_CATALOG", "bounded context selected by source order", "AVAILABLE"), new EvidenceAuthority("FROZEN_SOURCE_CATALOG", "source path extension", "AVAILABLE") }, missing, ProjectionVersion, fingerprint, configHash);
    }
    private static PairOccurrence Core(Occurrence x, SourceDoc source) => new(x.NodeId, x.Text, Normalize(x.Text), x.DocumentOrder, SourceKind(source.SourcePath), SourceContainer(x.NodeId));
    private static IReadOnlyList<PairOccurrence> Neighbors(IReadOnlyList<Occurrence> all, int index, int direction, int count, SourceDoc source) => (direction < 0 ? all.Take(index).TakeLast(count) : all.Skip(index + 1).Take(count)).Select(x => Core(x, source)).ToArray();
    private static IReadOnlyList<Occurrence> Bounded(IReadOnlyList<Occurrence> all, int max) => all.Count <= max ? all : all.Take(max / 2).Concat(all.TakeLast(max - max / 2)).ToArray();
    private static IReadOnlyList<StructuralPeer> StructuralPeers(IReadOnlyList<Occurrence> nodes, int left, int right) => nodes.Select((x, i) => (x, i)).Where(x => (x.i == left || x.i == right) && SourceContainer(x.x.NodeId).Length > 0).SelectMany(anchor => nodes.Select((x, i) => (x, i)).Where(x => x.i != left && x.i != right && SourceContainer(x.x.NodeId) == SourceContainer(anchor.x.NodeId)).OrderBy(x => Math.Abs(x.i - anchor.i)).ThenBy(x => x.x.NodeId, StringComparer.Ordinal).Take(MaxStructuralPeers)).Select(x => new StructuralPeer(x.x.NodeId, x.x.DocumentOrder, SourceContainer(x.x.NodeId))).DistinctBy(x => x.SourceOccurrenceId).OrderBy(x => x.DocumentOrder).ThenBy(x => x.SourceOccurrenceId, StringComparer.Ordinal).Take(MaxStructuralPeers).ToArray();
    private static IEnumerable<string> PacketOccurrenceIds(Packet p) => p.PairCore.Select(x => x.SourceOccurrenceId).Concat(p.LocalContext.PreviousOfLeft.Select(x => x.SourceOccurrenceId)).Concat(p.LocalContext.NextOfLeft.Select(x => x.SourceOccurrenceId)).Concat(p.LocalContext.PreviousOfRight.Select(x => x.SourceOccurrenceId)).Concat(p.LocalContext.NextOfRight.Select(x => x.SourceOccurrenceId)).Concat(p.LocalContext.Intervening.Select(x => x.SourceOccurrenceId)).Concat(p.StructuralContext.StructuralPeers.Select(x => x.SourceOccurrenceId));
    private static string PacketClass(Packet p) => p.StructuralContext.StructuralPeers.Count > 0 ? "STRUCTURALLY_PARTIAL" : p.LocalContext.Intervening.Count > 0 || p.LocalContext.PreviousOfLeft.Count > 0 || p.LocalContext.NextOfRight.Count > 0 ? "LOCAL_ONLY" : "PAIR_ONLY";
    private static object BuildAvailability(IReadOnlyList<Analysis> a) { var total = a.Count; int Count(Func<Packet, bool> f) => a.Count(x => f(x.Packet)); return new { artifactKind = "a99_identity_benchmark_v4f_b_evidence_availability", sourceOnly = true, packetCount = total, pairCore = Stat(total, total), localContext = Stat(Count(p => p.LocalContext.PreviousOfLeft.Count + p.LocalContext.NextOfLeft.Count + p.LocalContext.PreviousOfRight.Count + p.LocalContext.NextOfRight.Count > 0), total), structuralContext = Stat(Count(p => p.StructuralContext.StructuralPeers.Count > 0), total), scope = Stat(0, total), numbering = Stat(0, total), branchMarkers = Stat(Count(p => p.RelationalFacts.LeftBranchMarkers.Count + p.RelationalFacts.RightBranchMarkers.Count > 0), total), interveningOccurrences = Stat(Count(p => p.LocalContext.Intervening.Count > 0), total), layout = Stat(0, total), visual = Stat(0, total), classes = a.GroupBy(x => PacketClass(x.Packet), StringComparer.Ordinal).OrderBy(x => x.Key, StringComparer.Ordinal).Select(x => new { packetClass = x.Key, count = x.Count(), share = Ratio(x.Count(), total) }).ToArray() }; }
    private static object Stat(int count, int total) => new { count, percentage = Ratio(count, total) };
    private static object BuildSize(IReadOnlyList<Analysis> a) => new { artifactKind = "a99_identity_benchmark_v4f_b_packet_size_distribution", schemaVersion = "a99-v4f-b-packet-size-distribution-v1", oldRequestBytes = Distribution(a.Select(x => (long)x.OldBytes)), newPacketBytes = Distribution(a.Select(x => (long)x.Bytes)), oldEstimatedTokens = Distribution(a.Select(x => (long)Estimate(checked((int)x.OldBytes)))), newEstimatedTokens = Distribution(a.Select(x => (long)Estimate(x.Bytes))), comparison = new { oldTotalBytes = a.Sum(x => (long)x.OldBytes), newTotalBytes = a.Sum(x => (long)x.Bytes), reductionBytes = a.Sum(x => (long)x.OldBytes) - a.Sum(x => (long)x.Bytes), reductionPercentage = Ratio(a.Sum(x => (long)x.OldBytes) - a.Sum(x => (long)x.Bytes), a.Sum(x => (long)x.OldBytes)), compressionRatio = a.Sum(x => (double)x.OldBytes) / Math.Max(1, a.Sum(x => (double)x.Bytes)) }, perDocument = a.GroupBy(x => x.DocumentId, StringComparer.Ordinal).OrderBy(x => x.Key, StringComparer.Ordinal).Select(x => new { documentId = x.Key, old = Distribution(x.Select(y => (long)y.OldBytes)), @new = Distribution(x.Select(y => (long)y.Bytes)), reductionPercentage = Ratio(x.Sum(y => (long)y.OldBytes) - x.Sum(y => (long)y.Bytes), x.Sum(y => (long)y.OldBytes)) }).ToArray() };
    private static object BuildPayload(IReadOnlyList<Analysis> a) { long total = a.Sum(x => (long)x.Bytes); long pair = 0, local = 0, structural = 0, relational = 0, metadata = 0; foreach (var x in a) { pair += JsonSerializer.SerializeToUtf8Bytes(x.Packet.PairCore, WriteOptions).Length; local += JsonSerializer.SerializeToUtf8Bytes(x.Packet.LocalContext, WriteOptions).Length; structural += JsonSerializer.SerializeToUtf8Bytes(x.Packet.StructuralContext, WriteOptions).Length; relational += JsonSerializer.SerializeToUtf8Bytes(x.Packet.RelationalFacts, WriteOptions).Length; metadata += JsonSerializer.SerializeToUtf8Bytes(new { x.Packet.CandidateId, x.Packet.DocumentId, x.Packet.EvidenceAuthorities, x.Packet.MissingEvidence, x.Packet.ProjectionVersion, x.Packet.SourceCatalogFingerprint, x.Packet.ProjectionConfigSha256 }, WriteOptions).Length; } var other = total - pair - local - structural - relational - metadata; return new { artifactKind = "a99_identity_benchmark_v4f_b_payload_decomposition", schemaVersion = "a99-v4f-b-payload-decomposition-v1", method = "component JSON byte accounting plus serialization residual", totals = new { totalBytes = total, pairSpecificBytes = pair, localContextBytes = local, structuralContextBytes = structural, relationalFactsBytes = relational, staticSchemaMetadataBytes = metadata, otherBytes = other, exactSum = pair + local + structural + relational + metadata + other == total }, percentages = new { pairSpecific = Ratio(pair, total), localContext = Ratio(local, total), structuralContext = Ratio(structural, total), relationalFacts = Ratio(relational, total), staticMetadata = Ratio(metadata, total), other = Ratio(other, total) } }; }
    private static object Distribution(IEnumerable<long> values) { var v = values.OrderBy(x => x).ToArray(); return new { count = v.Length, min = v.DefaultIfEmpty(0).Min(), p50 = Percentile(v, .5), p75 = Percentile(v, .75), p90 = Percentile(v, .9), p95 = Percentile(v, .95), p99 = Percentile(v, .99), max = v.DefaultIfEmpty(0).Max(), mean = v.Length == 0 ? 0 : Math.Round(v.Average(), 3), total = v.Sum() }; }
    private static long Percentile(long[] v, double p) => v.Length == 0 ? 0 : v[Math.Min(v.Length - 1, (int)Math.Floor(p * (v.Length - 1)))];
    private static string BuildReport(IReadOnlyList<Analysis> a, IReadOnlyDictionary<string, SourceDoc> docs, string configHash) { var old = a.Sum(x => (long)x.OldBytes); var @new = a.Sum(x => (long)x.Bytes); return $"# A99 V4F-B — bounded local identity evidence projection\n\nStatus: **READY_FOR_V4F_PROJECTED_REQUEST_FREEZE**\n\nThis is a source-only counterfactual projection. It preserves all **{a.Count:N0}** frozen candidate pairs and does not call a model/provider or read Gold/V4E-B evaluation.\n\n## Contract\n\n- Pair core: source occurrence IDs, raw/comparison surfaces, source kind, document order and parser-owned source container.\n- Local context: previous/next bounds `{PreviousOccurrenceCount}/{NextOccurrenceCount}` and at most `{MaxInterveningOccurrences}` intervening occurrences.\n- Structural context: bounded same-container peers (`{MaxStructuralPeers}`); no fabricated ancestor, numbering, scope, layout or visual facts.\n- Semantic conclusions are not projected. The projection configuration hash is `{configHash}`.\n\n## Size\n\n- Old frozen request context: **{old:N0} bytes** / **{a.Sum(x => (long)Estimate(x.OldBytes)):N0} estimated tokens**.\n- New projected packets: **{@new:N0} bytes** / **{a.Sum(x => (long)Estimate(x.Bytes)):N0} estimated tokens**.\n- Reduction: **{old - @new:N0} bytes ({Ratio(old - @new, old):P4})**; compression ratio **{old / (double)Math.Max(1, @new):N2}x**.\n\nThe complete distributions and per-document values are in `packet-size-distribution.json`; packet bodies are not persisted.\n\n## Coverage\n\n`evidence-availability.json` reports pair core, bounded local/structural evidence, literal branch/continuation marker facts, and unavailable fields. Packet classes are descriptive only: `STRUCTURALLY_PARTIAL`, `LOCAL_ONLY`, `PAIR_ONLY`. No semantic sufficiency claim is made.\n\n## Firewall\n\n`GoldReadCount=0`; `V4EBEvaluationReadCount=0`; `ProviderCalls=0`; `ModelCalls=0`; candidate set changed=false; candidate order does not affect canonical packet set; no relation conclusions; no request prompt change.\n\n## Gate\n\n**READY_FOR_V4F_PROJECTED_REQUEST_FREEZE**. The next authorized step is to freeze canonical projected verifier requests for the same 7,702 candidates, still with zero provider calls.\n"; }
    private static string Normalize(string text) => string.Join(' ', text.Normalize(NormalizationForm.FormKC).Split((char[]?)null, StringSplitOptions.RemoveEmptyEntries));
    private static string[] Markers(string text) => ContinuationMarker.Matches(text).Select(x => x.Value).Order(StringComparer.Ordinal).ToArray();
    private static string[] Branches(string text) => BranchMarker.Matches(text).Select(x => x.Value).Order(StringComparer.Ordinal).ToArray();
    private static string SourceContainer(string id) { var p = id.Split(':', 2).ElementAtOrDefault(1) ?? id; return p.Split('/').FirstOrDefault() ?? string.Empty; }
    private static string SourceKind(string path) => Path.GetExtension(path).Equals(".pdf", StringComparison.OrdinalIgnoreCase) ? "PDF" : "SOURCE_PACKET";
    private static int Estimate(int bytes) => (bytes + 3) / 4;
    private static int Estimate(long bytes) => checked((int)((bytes + 3) / 4));
    private static Candidate ReadCandidate(JsonElement x) => new(x.GetProperty("pairId").GetString()!, x.GetProperty("documentId").GetString()!, x.GetProperty("left").GetString()!, x.GetProperty("right").GetString()!, x.TryGetProperty("reasons", out var r) ? r.EnumerateArray().Select(y => y.GetString()!).ToArray() : []);
    private static JsonDocument Read(string path) => JsonDocument.Parse(File.ReadAllText(path));
    private static string DocumentOf(string id) => id.Split(':', 2)[0];
    private static string Full(string root, string path) => Path.Combine(root, path.Replace('/', Path.DirectorySeparatorChar));
    private static string Sha256File(string path) => Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(path))).ToLowerInvariant();
    private static string Sha256Text(string text) => Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(text))).ToLowerInvariant();
    private static double Ratio(long n, long d) => d == 0 ? 0 : Math.Round(n / (double)d, 8);
    private static void Write(string path, object value) => File.WriteAllText(path, JsonSerializer.Serialize(value, WriteOptions) + Environment.NewLine, new UTF8Encoding(false));
    private static Verification VerifyInputs(JsonDocument source, JsonDocument manifest, JsonDocument shortlist, JsonDocument requests, string sourcePath, string manifestPath, string shortlistPath, string requestPath)
    {
        var f = new List<string>(); var m = manifest.RootElement; var s = shortlist.RootElement; var r = requests.RootElement;
        void Check(bool ok, string n) { if (!ok) f.Add(n); }
        Check(m.GetProperty("shortlistedCount").GetInt32() == ExpectedCount, "v4e.shortlistedCount"); Check(m.GetProperty("requestCount").GetInt32() == ExpectedCount, "v4e.requestCount"); Check(s.GetProperty("candidates").GetArrayLength() == ExpectedCount, "shortlist.count"); Check(r.GetProperty("requestCount").GetInt32() == ExpectedCount, "request.count");
        Check(Sha256File(shortlistPath) == m.GetProperty("shortlistSha256").GetString(), "shortlist.sha256"); Check(Sha256File(requestPath) == m.GetProperty("requestManifestSha256").GetString(), "request.sha256"); Check(Sha256File(sourcePath) == m.GetProperty("sourceCatalogSha256").GetString(), "source.sha256"); Check(source.RootElement.GetProperty("catalogFingerprint").GetString() == m.GetProperty("sourceCatalogFingerprint").GetString(), "catalog.fingerprint"); Check(r.GetProperty("goldDerivedInput").GetBoolean() == false, "request.goldDerivedInput"); Check(source.RootElement.GetProperty("goldDerivedInput").GetBoolean() == false, "source.goldDerivedInput"); Check(m.GetProperty("goldReadCount").GetInt32() == 0 && m.GetProperty("providerCalls").GetInt32() == 0, "v4e.firewall"); return new(f.Count == 0, f);
    }

    private sealed record SourceDoc(string DocumentId, string SourceSha256, string SourcePath);
    private sealed record Occurrence(string NodeId, string Text, int DocumentOrder);
    private sealed record Candidate(string PairId, string DocumentId, string Left, string Right, IReadOnlyList<string> Reasons);
    private sealed record PairOccurrence(string SourceOccurrenceId, string RawSurface, string CanonicalComparisonSurface, int DocumentOrder, string SourceKind, string SourceContainer);
    private sealed record LocalContext(IReadOnlyList<PairOccurrence> PreviousOfLeft, IReadOnlyList<PairOccurrence> NextOfLeft, IReadOnlyList<PairOccurrence> PreviousOfRight, IReadOnlyList<PairOccurrence> NextOfRight, IReadOnlyList<PairOccurrence> Intervening, bool InterveningTruncated, int TotalInterveningOccurrences);
    private sealed record StructuralPeer(string SourceOccurrenceId, int DocumentOrder, string SourceContainer);
    private sealed record StructuralContext(IReadOnlyList<string> SourceContainers, IReadOnlyList<StructuralPeer> StructuralPeers);
